{
  "overall_decision": "manual_review",
  "chapters": [
    {
      "chapter_id": "1B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0011",
          "reason": "Treat as rhetorical anti-nuclear context only; it does not show an operational 2022 existential-risk decision."
        },
        {
          "evidence_id": "E0015",
          "reason": "Climate-forum rhetoric is broad catastrophe framing, not chapter-specific nuclear or security conduct."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct 2022 ruler-attributed existential-risk choice under Buhari's own authority",
          "lenses": ["1B.1", "1B.3", "1B.8", "1B.10"],
          "best_source_or_query_direction": "NNRA/NAEC 2022 annual reports, IAEA safeguards-implementation material, and any declassified presidential or security-council records on 2022 nuclear-security decisions",
          "why_it_matters": "Without a target-period choice, the chapter rests mostly on inherited posture and rhetoric."
        },
        {
          "gap": "Independent corroboration of the HEU-to-LEU conversion and other nuclear-security claims",
          "lenses": ["1B.3", "1B.9"],
          "best_source_or_query_direction": "IAEA, NNRA, and technical reporting that explicitly verifies the conversion and 2022 safeguards status",
          "why_it_matters": "This would separate self-report from demonstrated risk reduction."
        }
      ],
      "reason": "The package fairly establishes limited exposure and an anti-proliferation posture, but the direct 2022 ruler-level nuclear decision record is thin and much of the positive material is institutional or rhetorical rather than operational."
    },
    {
      "chapter_id": "2B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0025",
          "reason": "Treat the Lake Chad arms-flow assertion as contested rhetoric; VOA says the claim was unsubstantiated."
        },
        {
          "evidence_id": "E0029",
          "reason": "ECOWAS summit coverage is regional context, not Buhari-specific conduct, and should not be over-attributed."
        }
      ],
      "material_gaps": [
        {
          "gap": "Independent evidence of actual conflict-management effect from Buhari's Ukraine/ECOWAS diplomacy",
          "lenses": ["2B.1", "2B.7", "2B.10"],
          "best_source_or_query_direction": "ECOWAS communiqués, UN voting/mediation records, and third-party reporting on Nigeria's concrete mediation role or outcomes",
          "why_it_matters": "The package currently shows diplomacy and evacuation, but not much independently verified effect."
        },
        {
          "gap": "Direct documentary support for the contested Lake Chad weapons claim or any concrete cross-border security outcome",
          "lenses": ["2B.3", "2B.6", "2B.8"],
          "best_source_or_query_direction": "Independent security/arms-trafficking reporting, regional monitoring, and official border-control records",
          "why_it_matters": "This avoids over-weighting one unsupported presidential claim."
        }
      ],
      "reason": "The package captures no aggressive-war conduct and does show evacuation plus diplomatic restraint, but the strongest positives are rhetorical or self-reported and the one coercive regional-security claim is contested."
    },
    {
      "chapter_id": "3B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "More precise chain-of-command and federal-versus-state attribution for abuses and remedies",
          "lenses": ["3B.2", "3B.4", "3B.5", "3B.9"],
          "best_source_or_query_direction": "Primary court findings, inquiry records, and human-rights monitoring that distinguish federal action from state/local conduct",
          "why_it_matters": "This would sharpen how much of the abuse pattern is directly Buhari-attributable versus institutional or subnational."
        }
      ],
      "reason": "Strong and balanced: multiple independent sources show recurring state-linked abuse, partial remedies, crisis response, and clear contrary evidence, with attribution appropriately qualified."
    },
    {
      "chapter_id": "4B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0055",
          "reason": "Duplicate Reuters-family succession coverage of the same exit event; keep only one Reuters chain as corroboration."
        },
        {
          "evidence_id": "E0057",
          "reason": "Indirect media-environment context, not a direct Buhari order, so it should not carry personal-conduct weight by itself."
        }
      ],
      "material_gaps": [
        {
          "gap": "More direct evidence on Buhari's personal role in media and protest restrictions, beyond security-service and state-level actions",
          "lenses": ["4B.3", "4B.6", "4B.9"],
          "best_source_or_query_direction": "Court records, presidential directives, and independent press-freedom monitoring tied to specific 2022 incidents",
          "why_it_matters": "This is needed to separate Buhari's own choices from inherited institutional coercion."
        },
        {
          "gap": "Independent implementation evidence for the 2022 Electoral Act and related reforms",
          "lenses": ["4B.1", "4B.2", "4B.4", "4B.10"],
          "best_source_or_query_direction": "INEC post-election reports, observer mission final reports, and legislative/court records on implementation disputes",
          "why_it_matters": "The package currently leans on reform intent and partial early effects more than full-year implementation."
        }
      ],
      "reason": "The package shows both reform and repression, but much of the anti-authoritarian evidence is indirect or state-level, and the positive reform record relies heavily on Buhari's own framing and partial implementation claims."
    },
    {
      "chapter_id": "5B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "More household-level and distributional evidence on the effects of subsidy, naira redesign, and fiscal choices",
          "lenses": ["5B.8", "5B.9", "5B.10"],
          "best_source_or_query_direction": "Household survey analysis, poverty/welfare microdata, and independent distributional studies for 2022",
          "why_it_matters": "The package is strong on macro direction but less precise on who gained or lost."
        },
        {
          "gap": "Cleaner evidence on whether economic appointees were selected for competence versus loyalty",
          "lenses": ["5B.2", "5B.5"],
          "best_source_or_query_direction": "Personnel analysis, audit/investigative reporting, and formal appointment records with merit criteria",
          "why_it_matters": "This would sharpen the staffing side of the competence record."
        }
      ],
      "reason": "The package fairly presents a mixed macroeconomic record with independent downside evidence and clear policy choices, though some attribution remains mediated by inherited shocks and technocratic institutions."
    },
    {
      "chapter_id": "6B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0084",
          "reason": "Self-reported delivery tally; useful as context, but it needs independent audit before it can count as strong evidence of delivered welfare."
        },
        {
          "evidence_id": "E0091",
          "reason": "National poverty baseline and inherited deprivation context, not direct evidence of Buhari-specific welfare causation."
        }
      ],
      "material_gaps": [
        {
          "gap": "Independent outcome evaluation of school feeding, BHCPF, rotavirus rollout, and related social programs",
          "lenses": ["6B.2", "6B.4", "6B.6", "6B.9"],
          "best_source_or_query_direction": "Audits, implementation evaluations, and third-party monitoring from WHO/UNICEF/World Bank or Nigerian oversight bodies",
          "why_it_matters": "The chapter currently has more plan-and-rollout evidence than verified delivery quality."
        },
        {
          "gap": "Subnational delivery and attribution, especially for north-south and rural-urban differences",
          "lenses": ["6B.3", "6B.8", "6B.10"],
          "best_source_or_query_direction": "State-level survey breakdowns, program audits, and subnational welfare analysis",
          "why_it_matters": "This would distinguish national policy from uneven local execution and inherited gaps."
        }
      ],
      "reason": "The welfare record is plausible and well sourced, but much of the positive delivery evidence is self-reported or survey-level, so target-period causal attribution and implementation quality still need tightening."
    },
    {
      "chapter_id": "7B",
      "decision": "manual_review",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0099",
          "reason": "Self-assessment transcript; it is direct ruler speech, but it is not independent proof of honesty or integrity."
        },
        {
          "evidence_id": "E0108",
          "reason": "Interpretive academic-style criticism accessed through ResearchGate; use as context and corroboration, not as decisive proof."
        },
        {
          "evidence_id": "E0107",
          "reason": "Media-environment synthesis, not a direct ruler act, so it should not be treated as standalone proof of Buhari's personal dishonesty."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct evidence on assets, beneficial ownership, gifts, campaign finance, or family enrichment",
          "lenses": ["7B.3", "7B.4"],
          "best_source_or_query_direction": "Asset-declaration records, procurement/audit investigations, and court or legislative findings on conflicts of interest",
          "why_it_matters": "This is the main missing pillar for a personal-integrity judgment."
        },
        {
          "gap": "More independent evidence on truthfulness, correction, and acceptance of scrutiny",
          "lenses": ["7B.1", "7B.2", "7B.6", "7B.7"],
          "best_source_or_query_direction": "Fact-checks, court records, oversight findings, and contemporaneous reporting on Buhari's own claims and corrections",
          "why_it_matters": "The package currently over-relies on official self-presentation and indirect institutional context."
        },
        {
          "gap": "Better separation of Buhari's personal conduct from broader authoritarian or state-level behavior",
          "lenses": ["7B.5", "7B.9", "7B.10"],
          "best_source_or_query_direction": "Personnel-analysis reporting and direct evidence of Buhari's own appointment, protection, or concealment choices",
          "why_it_matters": "This chapter needs clearer personal nexus than the current dossier provides."
        }
      ],
      "reason": "This chapter is not yet cleanly reviewable as a final package: it mixes direct personal-nexus evidence with context-heavy self-report and interpretive sources, while independent proof of personal integrity failures, safeguards, assets, and conflict-of-interest handling remains too thin."
    },
    {
      "chapter_id": "8B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0119",
          "reason": "Long-run diagnostic context; useful for trajectory, but it is not direct evidence of a specific 2022 execution choice."
        }
      ],
      "material_gaps": [
        {
          "gap": "Audited completion data for major projects and service-delivery claims",
          "lenses": ["8B.2", "8B.6", "8B.7"],
          "best_source_or_query_direction": "Independent project audits, ministry completion reports, and procurement/implementation records",
          "why_it_matters": "The dossier shows plans and machinery, but weaker verified completion evidence."
        },
        {
          "gap": "Independent evidence that coordination bodies and new appointments changed implementation quality",
          "lenses": ["8B.3", "8B.5", "8B.8", "8B.10"],
          "best_source_or_query_direction": "Internal performance reviews, external evaluations, and sector outcome studies tied to the 2022 coordination changes",
          "why_it_matters": "This would show whether the administrative scaffolding actually improved execution."
        }
      ],
      "reason": "The package covers program articulation and implementation scaffolding well, but end-of-year effectiveness evidence is mixed and still too dependent on official self-report for a strong final comparative judgment."
    }
  ]
}
